            });

            var candidate = candidates.splice(0, 1)[0];
            bwg._tsFetch(candidate.zoom, candidate.chr, candidate.min, candidate.max, function(feats) {
                var rp = dir > 0 ? 0 : 300000000;
                if (candidate.fromRef)
