@Input()
  set chips(value: any) {
    this.value = [];
    for (const v of value) {
      const isExited = this.value.find((elem) => {
        return elem.value === v.value;
      });
      if (!isExited) {
        this.value.push(v);
      }
    }
  }

get chips(): any {
    return this.value;
  }

ngOnInit() {
    this.setChipClass();
  }

setChipClass() {
    this.chipClass = {
      'free-chip-input': this.placeholder,
      'free-chip-focus': this.focus
    };
  }

addGroup(value: ChipComponent) {
    this.groups.push(value);
    if (this.placeholder) {
      this.onChange.emit(this.value);
    }
  }

removeGroup(value: ChipComponent) {
    const index = this.value.findIndex((elem) => {
      return elem.value === value.value;
    });
    if (index !== -1) {
      this.groups.splice(index, 1);
      this.value.splice(index, 1);
      this.onChange.emit(this.value);
    }
  }

onFocus() {
    this.focus = !this.focus;
    this.setChipClass();
  }

onEnter(event: any) {
    const value = event.target.value.trim();
    if (value) {
      this.chips.push({
        value: value,
        delete: true
      });
      this.value.push(value);
      this.chips = this.chips.slice();
      event.target.value = '';
    }
  }

